#[derive(Clone)]
pub struct ProviderSessionIdentity {
    thread_id: String,
    driver: Arc<dyn ProviderDriver>,
}

enum SupervisorMessage {
    Launch {
        request: Box<ProviderLaunchRequest>,
        context_handoff: bool,
        /// The frozen start this launch resumes the conversation for.
        frozen_delivery: Option<Box<ProviderTurnDelivery>>,
        /// Fail with `FrozenConversationLost`, keeping the saved cursor, instead of continuing in
        /// a new conversation when the requested one is gone.
        abort_on_lost_resume: bool,
        /// The frozen start released into a new conversation, when the old one was gone.
        response: oneshot::Sender<Result<Option<ProviderTurnDelivery>, ProviderRuntimeError>>,
    },
    Handle {
        command: Box<OrchestrationCommand>,
        response: oneshot::Sender<Result<(), ProviderRuntimeError>>,
    },
    Rewind {
        thread_id: String,
        turn_count: i64,
        rewind_key: String,
        response: oneshot::Sender<Result<ProviderRewind, ProviderRuntimeError>>,
    },
    CaptureSessionIdentity {
        thread_id: String,
        response: oneshot::Sender<Result<Option<ProviderSessionIdentity>, ProviderRuntimeError>>,
    },
    StopSessionIfCurrent {
        identity: ProviderSessionIdentity,
        response: oneshot::Sender<Result<(), ProviderRuntimeError>>,
    },
    SuspendSessionForRemovalIfCurrent {
        identity: ProviderSessionIdentity,
        response: oneshot::Sender<Result<(), ProviderRuntimeError>>,
    },
    SettleSessionAfterWorkspaceLoss {
        thread_id: String,
        identity: Option<ProviderSessionIdentity>,
        response: oneshot::Sender<Result<(), ProviderRuntimeError>>,
    },
    SessionStreamEnded {
        identity: ProviderSessionIdentity,
        settled: oneshot::Receiver<()>,
    },
    Deliver {
        command: Box<OrchestrationCommand>,
        delivery_key: String,
        frozen_delivery: Option<Box<ProviderTurnDelivery>>,
        response: oneshot::Sender<Result<ProviderDeliveryHandle, ProviderRuntimeError>>,
    },
    Reconcile {
        row: Box<ProviderTurnDelivery>,
        response: oneshot::Sender<Result<ProviderReconciliationOutcome, ProviderRuntimeError>>,
    },
    SetAgentActivityEnabled {
        enabled: bool,
        response: oneshot::Sender<Result<usize, ProviderRuntimeError>>,
    },
    CancelActivityTarget {
        scope: ActivityScopeRef,
        generation: ActivityRuntimeGeneration,
        target: ProviderActivityNativeTarget,
        response: oneshot::Sender<Result<ActivityTargetDispatchDisposition, ProviderRuntimeError>>,
    },
    InvalidateActivityControls {
        thread_id: String,
        generation: ActivityRuntimeGeneration,
        response: oneshot::Sender<()>,
    },
    #[cfg(test)]
    InspectActivityRuntimeGeneration {
        thread_id: String,
        response: oneshot::Sender<Option<ActivityRuntimeGeneration>>,
    },
    Shutdown {
        response: oneshot::Sender<Result<(), ProviderRuntimeError>>,
    },
    PublishAcceptedDelivery {
        identity: ProviderSessionIdentity,
        generation: u64,
        terminal_revision: u64,
        turn_id: Option<String>,
        response: oneshot::Sender<()>,
    },
    DeliveryComplete {
        thread_id: String,
        generation: u64,
        abnormal: bool,
    },
    DrainDeferred {
        thread_id: String,
        generation: u64,
    },
    SuspendIdle {
        thread_id: String,
        idle_generation: Arc<AtomicU64>,
        generation: u64,
    },
    InterruptDeadline {
        identity: ProviderSessionIdentity,
        turn_id: String,
    },
    ActivityDispatchTaskComplete {
        thread_id: String,
        generation: ActivityRuntimeGeneration,
        task_id: ActivityDispatchTaskId,
    },
    ActivityTargetUnsupported {
        thread_id: String,
        generation: ActivityRuntimeGeneration,
        response: oneshot::Sender<Result<ActivityTargetDispatchDisposition, ProviderRuntimeError>>,
        provider: String,
    },
}

