    struct CodexStartupMilestones {
        initialize_response_ready: Arc<FixtureEvent>,
        initialize_checkpoint: u64,
        thread_response_ready: Arc<FixtureEvent>,
        thread_checkpoint: u64,
        owner_completed: Arc<FixtureEvent>,
        owner_checkpoint: u64,
    }

    impl CodexStartupMilestones {
        fn new(
            initialize_response_ready: Arc<FixtureEvent>,
            thread_response_ready: Arc<FixtureEvent>,
            owner_completed: Arc<FixtureEvent>,
        ) -> Self {
            let initialize_checkpoint = initialize_response_ready.checkpoint();
            let thread_checkpoint = thread_response_ready.checkpoint();
            let owner_checkpoint = owner_completed.checkpoint();
            Self {
                initialize_response_ready,
                initialize_checkpoint,
                thread_response_ready,
                thread_checkpoint,
                owner_completed,
                owner_checkpoint,
            }
        }

        async fn wait_until(&self, deadline: tokio::time::Instant) -> Result<(), &'static str> {
            self.wait_for(
                &self.initialize_response_ready,
                self.initialize_checkpoint,
                deadline,
                "initialize_response_ready",
            )
            .await?;
            self.wait_for(
                &self.thread_response_ready,
                self.thread_checkpoint,
                deadline,
                "thread_response_ready",
            )
            .await?;
            self.wait_for(
                &self.owner_completed,
                self.owner_checkpoint,
                deadline,
                "owner_completed",
            )
            .await
        }

        async fn wait_for(
            &self,
            event: &FixtureEvent,
            checkpoint: u64,
            deadline: tokio::time::Instant,
            milestone: &'static str,
        ) -> Result<(), &'static str> {
            tokio::time::timeout_at(deadline, event.wait_after(checkpoint))
                .await
                .map_err(|_| milestone)
        }

        fn reached(&self) -> (bool, bool, bool) {
            (
                self.initialize_response_ready.checkpoint() > self.initialize_checkpoint,
                self.thread_response_ready.checkpoint() > self.thread_checkpoint,
                self.owner_completed.checkpoint() > self.owner_checkpoint,
            )
        }
    }

    #[tokio::test(start_paused = true)]
    async fn codex_startup_milestones_accept_owner_scheduled_after_two_seconds() {
        let initialize_response_ready = Arc::new(FixtureEvent::default());
        let thread_response_ready = Arc::new(FixtureEvent::default());
        let owner_completed = Arc::new(FixtureEvent::default());
        let milestones = CodexStartupMilestones::new(
            initialize_response_ready.clone(),
            thread_response_ready.clone(),
            owner_completed.clone(),
        );
        let observation =
            milestones.wait_until(tokio::time::Instant::now() + std::time::Duration::from_secs(15));
        tokio::pin!(observation);

        std::future::poll_fn(|context| {
            assert!(observation.as_mut().poll(context).is_pending());
            std::task::Poll::Ready(())
        })
        .await;
        tokio::time::advance(std::time::Duration::from_secs(3)).await;
        std::future::poll_fn(|context| {
            assert!(
                observation.as_mut().poll(context).is_pending(),
                "the obsolete two-second observer bound must not complete startup"
            );
            std::task::Poll::Ready(())
        })
        .await;

        initialize_response_ready.publish();
        std::future::poll_fn(|context| {
            assert!(
                observation.as_mut().poll(context).is_pending(),
                "initialize alone must not satisfy ordered startup"
            );
            std::task::Poll::Ready(())
        })
        .await;
        thread_response_ready.publish();
        std::future::poll_fn(|context| {
            assert!(
                observation.as_mut().poll(context).is_pending(),
                "responses alone must not satisfy owner completion"
            );
            std::task::Poll::Ready(())
        })
        .await;
        owner_completed.publish();

        observation
            .await
            .expect("all ordered milestones complete within the shared deadline");
    }

    #[tokio::test(start_paused = true)]
    async fn provider_fixture_deadline_is_not_restarted_between_milestones() {
        let started_at = tokio::time::Instant::now();
        let deadline = ProviderFixtureDeadline::after(std::time::Duration::from_secs(15));

        tokio::time::advance(std::time::Duration::from_secs(10)).await;
        deadline
            .observe(std::future::ready("first"))
            .await
            .expect("first milestone before the deadline");
        deadline
            .observe(std::future::pending::<()>())
            .await
            .expect_err("second milestone must retain the original deadline");

        assert_eq!(
            tokio::time::Instant::now().duration_since(started_at),
            std::time::Duration::from_secs(15),
        );
    }

    #[tokio::test(start_paused = true)]
    async fn provider_fixture_integration_deadline_preserves_loaded_suite_headroom() {
        let started_at = tokio::time::Instant::now();
        let deadline = ProviderFixtureDeadline::integration();

        tokio::time::advance(std::time::Duration::from_secs(16)).await;
        deadline
            .observe(std::future::pending::<()>())
            .await
            .expect_err("the integration fixture must remain bounded by one absolute deadline");

        assert_eq!(
            tokio::time::Instant::now().duration_since(started_at),
            std::time::Duration::from_secs(30),
        );
    }

    struct ProviderFixtureOwnerAbortProbe(Arc<AtomicBool>);

    impl Drop for ProviderFixtureOwnerAbortProbe {
        fn drop(&mut self) {
            self.0.store(true, Ordering::SeqCst);
        }
    }

    #[tokio::test]
    async fn provider_fixture_deadline_failure_aborts_owner_and_reaps_driver_before_panicking() {
        // Mutation caught: restoring an internal capture expect, or converting its deadline
        // error before cleanup, detaches the retained owner and leaves the fixture process live.
        let temp = TempDir::new().expect("provider fixture directory");
        let capture_path = temp.path().join("missing-capture.jsonl");
        let driver = cursor_delivery_fixture(&temp, &capture_path, None, false, false).await;
        driver.start().await.expect("Cursor fixture should start");

        let owner_aborted = Arc::new(AtomicBool::new(false));
        let (owner_started, owner_started_receiver) = tokio::sync::oneshot::channel();
        let owner_probe = owner_aborted.clone();
        let owner = tokio::spawn(async move {
            let _probe = ProviderFixtureOwnerAbortProbe(owner_probe);
            owner_started.send(()).expect("owner start observation");
            std::future::pending::<()>().await;
        });
        owner_started_receiver
            .await
            .expect("retained owner should start");

        let deadline = ProviderFixtureDeadline::after(std::time::Duration::ZERO);
        let capture_error = captured_request(deadline, &capture_path, |_| false)
            .await
            .expect_err("expired capture returns its deadline error to the cleanup owner");
        let cleanup_driver = driver.clone();
        let failure = tokio::spawn(async move {
            fixture_deadline_failure_with_owner(
                cleanup_driver.as_ref(),
                owner,
                "provider request capture",
                capture_error,
            )
            .await;
        });

        assert!(
            failure
                .await
                .expect_err("cleanup owner converts the deadline into the test failure")
                .is_panic(),
            "the deadline remains a test failure after cleanup"
        );
        assert!(
            owner_aborted.load(Ordering::SeqCst),
            "cleanup aborts and joins the retained owner before failing"
        );
        assert!(
            driver
                .child
                .lock()
                .await
                .try_wait()
                .expect("reaped fixture status")
                .is_some(),
            "cleanup shuts down and reaps the real fixture driver before failing"
        );
    }

    impl ProviderDriver for SupervisorDriver {
        fn holds_unsettled_work(&self) -> super::BoxRuntimeFuture<'_, bool> {
            Box::pin(std::future::ready(
                self.state.lock().unwrap().unsettled_work,
            ))
        }
        fn owns_native_work(&self) -> bool {
            !self.state.lock().unwrap().externally_owned
        }
        fn start(
            &self,
        ) -> super::BoxRuntimeFuture<'_, Result<super::StartedSession, super::ProviderRuntimeError>>
        {
            Box::pin(async move {
                self.state.lock().unwrap().starts += 1;
                Ok(super::StartedSession {
                    resume_cursor: Some(json!({"threadId":"unit-session"})),
                    runtime_payload: Some(json!({"transport":"unit"})),
                    activity_capabilities: self.state.lock().unwrap().activity_capabilities.clone(),
                })
            })
        }

        fn send(
            &self,
            text: String,
            _: Vec<Value>,
            _: String,
        ) -> super::BoxRuntimeFuture<'_, Result<Option<String>, super::ProviderRuntimeError>>
        {
            Box::pin(async move {
                let (gate, entered) = {
                    let state = self.state.lock().unwrap();
                    (state.send_gate.clone(), state.send_entered.clone())
                };
                if let Some(entered) = entered {
                    entered.notify_one();
                }
                if let Some(gate) = gate {
                    gate.notified().await;
                }
                let mut state = self.state.lock().unwrap();
                state.sends.push(text);
                Ok(Some(
                    state
                        .send_turn_ids
                        .pop_front()
                        .unwrap_or_else(|| "unit-turn".to_owned()),
                ))
            })
        }
        fn reconcile(
            &self,
            _delivery_key: String,
        ) -> super::BoxRuntimeFuture<'_, super::ProviderReconciliationOutcome> {
            Box::pin(async move {
                let gate = self.state.lock().unwrap().reconcile_gate.clone();
                if let Some(started) = self.state.lock().unwrap().reconcile_started.clone() {
                    started.notify_one();
                }
                if let Some(gate) = gate {
                    gate.notified().await;
                }
                super::ProviderReconciliationOutcome::Found
            })
        }

        fn interrupt(
            &self,
            _: Option<String>,
        ) -> super::BoxRuntimeFuture<'_, Result<(), super::ProviderRuntimeError>> {
            Box::pin(async move {
                let (entered, never_returns) = {
                    let mut state = self.state.lock().unwrap();
                    state.interrupts += 1;
                    (
                        state.interrupt_entered.clone(),
                        state.interrupt_never_returns,
                    )
                };
                if let Some(entered) = entered {
                    entered.notify_one();
                }
                if never_returns {
                    std::future::pending::<()>().await;
                }
                Ok(())
            })
        }

        fn approve(
            &self,
            _: String,
            _: String,
        ) -> super::BoxRuntimeFuture<'_, Result<(), super::ProviderRuntimeError>> {
            Box::pin(async move {
                self.state.lock().unwrap().approvals += 1;
                Ok(())
            })
        }

        fn answer(
            &self,
            _: String,
            _: Value,
        ) -> super::BoxRuntimeFuture<'_, Result<(), super::ProviderRuntimeError>> {
            Box::pin(async move {
                self.state.lock().unwrap().answers += 1;
                Ok(())
            })
        }

        fn set_mode(
            &self,
            mode: String,
        ) -> super::BoxRuntimeFuture<'_, Result<(), super::ProviderRuntimeError>> {
            Box::pin(async move {
                let mut state = self.state.lock().unwrap();
                state.modes.push(mode);
                if state.set_mode_unsupported {
                    return Err(super::ProviderRuntimeError::UnsupportedCapability {
                        provider: "codex".to_owned(),
                        capability: "runtime mode",
                    });
                }
                Ok(())
            })
        }

        fn set_interaction_mode(
            &self,
            mode: String,
        ) -> super::BoxRuntimeFuture<'_, Result<(), super::ProviderRuntimeError>> {
            Box::pin(async move {
                self.state.lock().unwrap().interaction_modes.push(mode);
                Ok(())
            })
        }

        fn cancel_activity_target(
            &self,
            target: ProviderActivityNativeTarget,
        ) -> super::BoxRuntimeFuture<
            '_,
            Result<super::ActivityTargetDispatchDisposition, super::ProviderRuntimeError>,
        > {
            Box::pin(async move {
                let (call_index, unsupported_after, hold_after, entered, release, active) = {
                    let mut state = self.state.lock().unwrap();
                    let target_label = target
                        .codex_turn_ids()
                        .map(|(thread_id, turn_id)| format!("codex:{thread_id}:{turn_id}"))
                        .or_else(|| {
                            target
                                .claude_task_id()
                                .map(|task_id| format!("claude:{task_id}"))
                        })
                        .expect("known target shape");
                    state.targeted_calls.push(target_label);
                    (
                        state.targeted_calls.len(),
                        state.targeted_unsupported_after,
                        state.targeted_hold_after,
                        state.targeted_entered.clone(),
                        state.targeted_release.clone(),
                        state.targeted_active.clone(),
                    )
                };
                active.fetch_add(1, Ordering::AcqRel);
                struct ActiveTarget(Arc<AtomicUsize>);
                impl Drop for ActiveTarget {
                    fn drop(&mut self) {
                        self.0.fetch_sub(1, Ordering::AcqRel);
                    }
                }
                let _active = ActiveTarget(active);
                if unsupported_after.is_some_and(|after| call_index >= after) {
                    return Err(super::ProviderRuntimeError::ActivityTargetUnsupported {
                        provider: "claudeAgent".to_owned(),
                    });
                }
                if hold_after.is_some_and(|hold_after| call_index >= hold_after) {
                    if let Some(entered) = entered {
                        entered.notify_one();
                    }
                    if let Some(release) = release {
                        release.notified().await;
                    }
                }
                Ok(super::ActivityTargetDispatchDisposition::Delivered)
            })
        }

        fn set_model(
            &self,
            model: String,
        ) -> super::BoxRuntimeFuture<'_, Result<(), super::ProviderRuntimeError>> {
            Box::pin(async move {
                self.state.lock().unwrap().models.push(model);
                Ok(())
            })
        }

        fn set_options(
            &self,
            _: Vec<Value>,
        ) -> super::BoxRuntimeFuture<'_, Result<(), super::ProviderRuntimeError>> {
            Box::pin(async { Ok(()) })
        }

        fn rollback(
            &self,
            turn_count: i64,
            _rewind_key: String,
        ) -> super::BoxRuntimeFuture<'_, Result<(), super::ProviderRuntimeError>> {
            Box::pin(async move {
                self.state.lock().unwrap().rollbacks.push(turn_count);
                Ok(())
            })
        }

        fn next_event(&self) -> super::BoxRuntimeFuture<'_, Option<super::ProviderEvent>> {
            Box::pin(async move { self.events.lock().await.recv().await })
        }

        fn exited_process(
            &self,
        ) -> super::BoxRuntimeFuture<'_, Option<(u32, std::process::ExitStatus)>> {
            Box::pin(std::future::ready(self.state.lock().unwrap().exited))
        }

        fn shutdown(&self) -> super::BoxRuntimeFuture<'_, Result<(), super::ProviderRuntimeError>> {
            Box::pin(async move {
                let (entered, release, active, max_active) = {
                    let state = self.state.lock().unwrap();
                    (
                        state.shutdown_entered.clone(),
                        state.shutdown_release.clone(),
                        state.shutdown_active.clone(),
                        state.max_shutdown_active.clone(),
                    )
                };
                let active_count = active.fetch_add(1, Ordering::AcqRel) + 1;
                max_active.fetch_max(active_count, Ordering::AcqRel);
                if let Some(entered) = entered {
                    entered.add_permits(1);
                }
                if let Some(release) = release {
                    release
                        .acquire()
                        .await
                        .expect("shutdown release remains open")
                        .forget();
                }
                active.fetch_sub(1, Ordering::AcqRel);
                self.state.lock().unwrap().shutdowns += 1;
                Ok(())
            })
        }
    }

    struct SupervisorFactory {
        state: Arc<StdMutex<SupervisorDriverState>>,
        events: StdMutex<Option<mpsc::Receiver<super::ProviderEvent>>>,
    }

    impl ProviderDriverFactory for SupervisorFactory {
        fn create(
            &self,
            request: super::ProviderLaunchRequest,
        ) -> super::BoxRuntimeFuture<'_, Result<Arc<dyn ProviderDriver>, super::ProviderRuntimeError>>
        {
            Box::pin(async move {
                self.state.lock().unwrap().launches += 1;
                self.state.lock().unwrap().launch_requests.push(request);
                Ok(Arc::new(SupervisorDriver {
                    state: self.state.clone(),
                    events: tokio::sync::Mutex::new(
                        self.events.lock().unwrap().take().expect("event receiver"),
                    ),
                }) as Arc<dyn ProviderDriver>)
            })
        }
    }

    type SequencedSupervisorDrivers = std::collections::VecDeque<(
        Arc<StdMutex<SupervisorDriverState>>,
        mpsc::Receiver<super::ProviderEvent>,
    )>;

    struct SequencedSupervisorFactory {
        drivers: StdMutex<SequencedSupervisorDrivers>,
    }

    impl ProviderDriverFactory for SequencedSupervisorFactory {
        fn create(
            &self,
            _: super::ProviderLaunchRequest,
        ) -> super::BoxRuntimeFuture<'_, Result<Arc<dyn ProviderDriver>, super::ProviderRuntimeError>>
        {
            Box::pin(async move {
                let (state, events) = self
                    .drivers
                    .lock()
                    .unwrap()
                    .pop_front()
                    .expect("sequenced provider driver");
                state.lock().unwrap().launches += 1;
                Ok(Arc::new(SupervisorDriver {
                    state,
                    events: tokio::sync::Mutex::new(events),
                }) as Arc<dyn ProviderDriver>)
            })
        }
    }

    async fn supervisor_engine() -> super::OrchestrationEngine {
        let database = Database::open_in_memory().await.unwrap();
        database
            .call(|connection| {
                run_migrations(connection, None)?;
                Ok(())
            })
            .await
            .unwrap();
        let engine = super::OrchestrationEngine::start(database, EngineOptions::default())
            .await
            .unwrap();
        for command in [
            json!({"type":"project.create","commandId":"project","projectId":"p1","title":"Project","workspaceRoot":"/tmp/project","createdAt":"2026-07-16T00:00:00Z"}),
            json!({"type":"thread.create","commandId":"thread","threadId":"t1","projectId":"p1","title":"Thread","kind":"workspace","modelSelection":{"instanceId":"codex","model":"gpt-5"},"runtimeMode":"full-access","interactionMode":"default","branch":null,"worktreePath":null,"createdAt":"2026-07-16T00:00:00Z"}),
        ] {
            engine
                .dispatch(serde_json::from_value(command).unwrap())
                .await
                .unwrap();
        }
        engine
    }

