    #[cfg(unix)]
    #[tokio::test]
    async fn claude_start_delivery_is_accepted_while_a_steer_echo_is_pending() {
        for settle in [false, true] {
            let (_temp, driver, _active, mut steer) = claude_pending_steer_fixture().await;
            if settle {
                claude_fixture_action(&driver, "settle").await;
                claude_fixture_output(&driver, "turn.completed").await;
            }
            let started = timeout(
                Duration::from_secs(5),
                driver.deliver(
                    "normal delivery".into(),
                    vec![],
                    "default".into(),
                    "next-key".into(),
                ),
            )
            .await
            .unwrap();
            let early = timeout(Duration::from_millis(50), &mut steer).await.ok();
            claude_fixture_action(&driver, "echo-block").await;
            let steered = if early.is_none() {
                Some(
                    timeout(Duration::from_secs(5), steer)
                        .await
                        .unwrap()
                        .unwrap(),
                )
            } else {
                None
            };
            let current = driver.runtime.lock().await.snapshot().turn_id;
            driver.shutdown().await.unwrap();
            assert!(
                matches!(started, super::ProviderDeliveryOutcome::Accepted { turn_id: Some(ref id) } if Some(id) == current.as_ref()),
                "normal delivery must not be refused by an outstanding steer: {started:?}"
            );
            assert!(
                early.is_none(),
                "a start echo must not acknowledge or cancel the steer: {early:?}"
            );
            assert!(
                matches!(steered, Some(super::ProviderDeliveryOutcome::Accepted { turn_id: Some(ref id) }) if Some(id) == current.as_ref()),
                "the steer echo attributes the runtime turn current at replay: {steered:?}"
            );
        }
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn claude_steer_process_or_session_retirement_after_write_is_ambiguous() {
        for (retirement, detail) in [
            (
                "exit",
                "Work Claude stopped before it confirmed it received this message.",
            ),
            (
                "stream-failure",
                "The session ended before Work Claude confirmed it received this message.",
            ),
            (
                "session-replacement",
                "The session ended before Work Claude confirmed it received this message.",
            ),
        ] {
            let (_temp, driver, _active, steer) = claude_pending_steer_fixture().await;
            match retirement {
                "exit" => claude_fixture_action(&driver, "exit").await,
                "stream-failure" => {
                    driver
                        .runtime
                        .lock()
                        .await
                        .handle_stream_failure("stream failed");
                }
                _ => {
                    let mut runtime = driver.runtime.lock().await;
                    let mut snapshot = runtime.snapshot();
                    snapshot.session_id = "replacement".into();
                    runtime.restore_from_snapshot(snapshot);
                }
            }
            let outcome = timeout(Duration::from_secs(5), steer)
                .await
                .unwrap()
                .unwrap();
            driver.shutdown().await.unwrap();
            // The uncertain delivery's detail reads as a plain sentence, not internal state.
            assert_eq!(
                outcome,
                super::ProviderDeliveryOutcome::Ambiguous {
                    detail: detail.to_owned()
                },
                "{retirement}"
            );
        }
    }

    #[tokio::test]
    async fn claude_steer_first_write_failure_is_definitely_not_sent() {
        struct RejectWrite {
            _owner: Box<dyn AsyncWrite + Send + Unpin>,
        }
        impl AsyncWrite for RejectWrite {
            fn poll_write(
                self: Pin<&mut Self>,
                _: &mut Context<'_>,
                _: &[u8],
            ) -> Poll<io::Result<usize>> {
                Poll::Ready(Err(io::Error::new(
                    io::ErrorKind::BrokenPipe,
                    "before the first byte",
                )))
            }
            fn poll_flush(self: Pin<&mut Self>, _: &mut Context<'_>) -> Poll<io::Result<()>> {
                Poll::Ready(Ok(()))
            }
            fn poll_shutdown(self: Pin<&mut Self>, _: &mut Context<'_>) -> Poll<io::Result<()>> {
                Poll::Ready(Ok(()))
            }
        }
        let temp = TempDir::new().unwrap();
        let capture = temp.path().join("unwritten.jsonl");
        let driver = claude_delivery_fixture(
            &temp,
            "claude-unwritten",
            CLAUDE_FIXTURE,
            &capture,
            None,
            None,
        )
        .await;
        driver.start().await.unwrap();
        let active = driver
            .send("initial".into(), vec![], "default".into())
            .await
            .unwrap()
            .unwrap();
        {
            let mut writer = driver.writer.lock().await;
            let original = std::mem::replace(&mut *writer, Box::new(tokio::io::sink()));
            *writer = Box::new(RejectWrite { _owner: original });
        }
        let outcome = driver
            .steer("follow up".into(), vec![], active, "key".into())
            .await;
        driver.shutdown().await.unwrap();
        assert!(
            matches!(
                outcome,
                super::ProviderDeliveryOutcome::DefinitelyNotSent { .. }
            ),
            "an error from the first write proves no bytes were sent: {outcome:?}"
        );
        assert!(
            driver
                .pending_acknowledgement
                .state
                .lock()
                .unwrap()
                .pending
                .is_empty()
        );
    }

    #[tokio::test]
    async fn claude_delivery_waits_for_the_replayed_user_message_before_accepting() {
        let temp = TempDir::new().expect("provider fixture directory");
        let capture_path = temp.path().join("claude-delivery.jsonl");
        let acknowledgement_gate = temp.path().join("release-acknowledgement");
        #[cfg(unix)]
        let request_ready_path = temp.path().join("request-ready");
        #[cfg(unix)]
        let (request_ready, mut acknowledgement_writer) = {
            use std::os::unix::fs::OpenOptionsExt;

            for path in [&request_ready_path, &acknowledgement_gate] {
                assert!(
                    std::process::Command::new("mkfifo")
                        .arg(path)
                        .status()
                        .expect("Claude delivery mkfifo starts")
                        .success(),
                    "Claude delivery FIFO is created"
                );
            }
            let open_fifo = |path: &std::path::Path| {
                std::fs::OpenOptions::new()
                    .read(true)
                    .write(true)
                    .custom_flags(libc::O_NONBLOCK)
                    .open(path)
                    .expect("open Claude delivery FIFO without blocking")
            };
            (
                tokio::io::unix::AsyncFd::new(open_fifo(&request_ready_path))
                    .expect("register Claude delivery readiness FIFO"),
                open_fifo(&acknowledgement_gate),
            )
        };
        let driver = claude_delivery_fixture(
            &temp,
            "claude-delivery-replay",
            CLAUDE_REPLAY_FIXTURE,
            &capture_path,
            Some(&acknowledgement_gate),
            {
                #[cfg(unix)]
                {
                    Some(request_ready_path.as_path())
                }
                #[cfg(windows)]
                {
                    None
                }
            },
        )
        .await;
        driver.start().await.expect("Claude fixture should start");
        let deadline = ProviderFixtureDeadline::integration();
        let delivery_driver = driver.clone();
        let mut delivery = tokio::spawn(async move {
            delivery_driver
                .deliver(
                    "hello".to_owned(),
                    Vec::new(),
                    "default".to_owned(),
                    "unused-no-id-key".to_owned(),
                )
                .await
        });
        #[cfg(unix)]
        if let Err(error) = deadline
            .observe(async {
                use std::io::Read;

                let mut bytes = [0_u8; 16];
                loop {
                    let mut readable = request_ready
                        .readable()
                        .await
                        .expect("Claude delivery readiness FIFO remains registered");
                    match readable.try_io(|inner| {
                        let mut file = inner.get_ref();
                        file.read(&mut bytes)
                    }) {
                        Ok(Ok(count)) if count > 0 => break,
                        Ok(Ok(_)) | Err(_) => continue,
                        Ok(Err(error)) => panic!("read Claude delivery readiness FIFO: {error}"),
                    }
                }
            })
            .await
        {
            fixture_deadline_failure_with_owner(
                driver.as_ref(),
                delivery,
                "Claude delivery FIFO readiness",
                error,
            )
            .await;
        }
        #[cfg(windows)]
        if let Err(error) =
            captured_request(deadline, &capture_path, |value| value["type"] == "user").await
        {
            fixture_deadline_failure_with_owner(
                driver.as_ref(),
                delivery,
                "Claude delivery request capture",
                error,
            )
            .await;
        }

        let premature = timeout(std::time::Duration::from_millis(100), &mut delivery).await;
        let was_pending = premature.is_err();
        #[cfg(unix)]
        {
            use std::io::Write;
            acknowledgement_writer
                .write_all(b"release\n")
                .expect("release acknowledgement");
        }
        #[cfg(windows)]
        std::fs::write(&acknowledgement_gate, b"release").expect("release acknowledgement");
        let outcome = match premature {
            Ok(outcome) => outcome.expect("delivery task should join"),
            Err(_) => match deadline.observe(&mut delivery).await {
                Ok(outcome) => outcome.expect("delivery task should join"),
                Err(error) => {
                    fixture_deadline_failure_with_owner(
                        driver.as_ref(),
                        delivery,
                        "Claude replay acknowledgement",
                        error,
                    )
                    .await
                }
            },
        };
        driver.shutdown().await.expect("Claude fixture shutdown");

        assert!(
            was_pending,
            "writing stdin is not acceptance; delivery must wait for Claude's replay"
        );
        assert!(matches!(
            outcome,
            super::ProviderDeliveryOutcome::Accepted { turn_id: Some(_) }
        ));
    }

