    async fn open_url_connect_service(
        temp: &TempDir,
    ) -> Arc<crate::production::connect_mcp::ConnectMcpService> {
        use crate::production::connect_mcp::{
            ConnectMcpConfig, ConnectMcpService, DecodedCloudProof, EndpointRuntime, JwtCodec,
            PairingIssuer, PreviewInvoker,
        };
        let jwt = JwtCodec::new(
            |_typ, _payload| async move { Err("unused".to_owned()) },
            |_key, _typ, _token, _issuer, _audience, _now| async move {
                Err::<DecodedCloudProof, _>("unused".to_owned())
            },
            || async { Err("unused".to_owned()) },
        );
        Arc::new(
            ConnectMcpService::open(
                temp.path().join("connect.sqlite3"),
                ConnectMcpConfig {
                    environment_id: "env-1".into(),
                    descriptor: json!({"environmentId":"env-1"}),
                    mcp_endpoint: "http://127.0.0.1:43123/mcp".into(),
                    open_url_endpoint: "http://127.0.0.1:43123/api/preview/open-url".into(),
                    now_epoch_seconds: Arc::new(|| 1_700_000_000),
                    max_mcp_credentials: 4,
                    max_mcp_sessions: 4,
                },
                jwt,
                EndpointRuntime::new(|_config| async move { Ok(json!({"status":"disabled"})) }),
                PairingIssuer::new(|_thumbprint| async move { Err("unused".to_owned()) }),
                PreviewInvoker::new(|_scope, _operation, _input, _tab, _cancellation| async {
                    Ok(json!({}))
                }),
            )
            .await
            .expect("connect service"),
        )
    }

    #[tokio::test]
    async fn provider_launch_env_contains_open_url_vars() {
        let engine = supervisor_engine().await;
        let state = Arc::new(StdMutex::new(SupervisorDriverState::default()));
        let (_events_tx, events) = mpsc::channel(1);
        let temp = TempDir::new().unwrap();
        let shim_dir = temp.path().join("shims");
        let supervisor = super::ProviderRuntimeSupervisor::start(
            engine.clone(),
            Arc::new(SupervisorFactory {
                state: state.clone(),
                events: StdMutex::new(Some(events)),
            }),
            super::ActivityProjection::new(crate::activity::ActivityRepository::new(
                engine.repositories().database().clone(),
            )),
            super::SupervisorOptions {
                open_url: Some(crate::open_url::OpenUrlEnvironment::new(shim_dir.clone())),
                ..super::SupervisorOptions::default()
            },
        );
        let connect = open_url_connect_service(&temp).await;
        supervisor.attach_connect_mcp(connect.clone()).await;
        let mut request = native_launch(&temp, "codex");
        request.thread_id = "t1".to_owned();
        let route_fingerprint = super::delivery_route_fingerprint(&request).unwrap();

        supervisor.launch(request).await.unwrap();

        let launched = state
            .lock()
            .unwrap()
            .launch_requests
            .pop()
            .expect("launched request");
        // The per-launch credential stays out of the durable route fingerprint.
        assert_eq!(
            super::delivery_route_fingerprint(&launched).unwrap(),
            route_fingerprint
        );
        let session = launched.open_url.clone().expect("open-url session");
        assert_eq!(
            connect.verify_open_url_credential(&session.token).await,
            Some("t1".to_owned())
        );
        assert_eq!(
            session.endpoint,
            "http://127.0.0.1:43123/api/preview/open-url"
        );
        assert_eq!(session.shim_dir, shim_dir);
        supervisor.shutdown().await.unwrap();
        engine.shutdown().await;

        // The provider process itself sees the variables.
        #[cfg(unix)]
        {
            let dump = temp.path().join("env-dump");
            let ready = temp.path().join("env-ready");
            let fixture = executable_fixture(
                &temp,
                "env-provider",
                &format!(
                    "#!/bin/sh\nprintf '%s\\n' \"$BIBCODE_OPEN_URL_AUTH\" \"$BIBCODE_OPEN_URL_ENDPOINT\" \"$BROWSER\" \"$BRAINSTORM_OPEN_CMD\" \"$PATH\" > '{}'\nprintf ready > '{}'\nread -r line\n",
                    dump.display(),
                    ready.display()
                ),
            );
            let mut launched = launched;
            launched.binary_path = fixture.to_string_lossy().into_owned();
            launched
                .environment
                .insert("BROWSER".to_owned(), "firefox".to_owned());
            let child =
                super::spawn_child(&launched, &[], false, ProcessAttributionRegistry::new())
                    .await
                    .expect("provider child should spawn");
            tokio::time::timeout(Duration::from_secs(5), async {
                while !ready.exists() {
                    tokio::time::sleep(Duration::from_millis(10)).await;
                }
            })
            .await
            .expect("provider fixture records its environment");
            let mut inner = child.into_inner();
            let _ = inner.start_kill();
            let _ = inner.wait().await;

            let recorded = std::fs::read_to_string(&dump).unwrap();
            let lines = recorded.lines().collect::<Vec<_>>();
            assert_eq!(lines[0], session.token);
            assert_eq!(lines[1], "http://127.0.0.1:43123/api/preview/open-url");
            assert_eq!(lines[2], "bibcode-open-url");
            assert_eq!(lines[3], "bibcode-open-url");
            assert!(
                lines[4].starts_with(&format!("{}:", shim_dir.display())),
                "PATH {} must start with the shim directory",
                lines[4]
            );
        }
    }

    #[tokio::test]
    async fn delivery_send_does_not_block_supervisor_control_messages() {
        let engine = supervisor_engine().await;
        let gate = Arc::new(tokio::sync::Notify::new());
        let state = Arc::new(StdMutex::new(SupervisorDriverState {
            send_gate: Some(gate.clone()),
            ..SupervisorDriverState::default()
        }));
        let (_events_tx, events) = mpsc::channel(1);
        let supervisor = super::ProviderRuntimeSupervisor::start(
            engine.clone(),
            Arc::new(SupervisorFactory {
                state: state.clone(),
                events: StdMutex::new(Some(events)),
            }),
            super::ActivityProjection::new(crate::activity::ActivityRepository::new(
                engine.repositories().database().clone(),
            )),
            super::SupervisorOptions::default(),
        );
        let temp = TempDir::new().unwrap();
        let mut request = native_launch(&temp, "codex");
        request.thread_id = "t1".to_owned();
        supervisor.launch(request).await.unwrap();
        let command: OrchestrationCommand = serde_json::from_value(json!({
            "type":"thread.turn.start", "commandId":"delivery", "threadId":"t1",
            "message":{"messageId":"message","role":"user","text":"hello","attachments":[]},
            "modelSelection":{"instanceId":"codex","model":"gpt-5"},
            "runtimeMode":"full-access", "interactionMode":"default",
            "createdAt":"2026-07-16T00:00:00Z"
        }))
        .unwrap();

        let handle = supervisor
            .deliver_turn(command, "delivery-1".to_owned())
            .await
            .unwrap();
        timeout(
            std::time::Duration::from_millis(100),
            supervisor.handle_orchestration(
                serde_json::from_value(json!({
                    "type":"thread.approval.respond", "commandId":"approval",
                    "threadId":"t1", "requestId":"request-1",
                    "decision":"accept", "createdAt":"2026-07-16T00:00:00Z"
                }))
                .unwrap(),
            ),
        )
        .await
        .expect("approval remains responsive")
        .unwrap();
        assert_eq!(state.lock().unwrap().approvals, 1);

        gate.notify_one();
        assert_eq!(
            handle.completion().await,
            super::ProviderDeliveryOutcome::Accepted {
                turn_id: Some("unit-turn".to_owned())
            }
        );
        supervisor.shutdown().await.unwrap();
        engine.shutdown().await;
    }

    #[tokio::test]
    async fn completed_idle_session_is_suspended_without_losing_resume_state() {
        const IDLE_TIMEOUT: Duration = Duration::from_secs(30);

        let engine = supervisor_engine().await;
        // A session that reports its subagents, so an empty report means idle.
        let state = Arc::new(StdMutex::new(SupervisorDriverState {
            activity_capabilities: crate::activity::ActivityCapabilities::structured_full(false),
            ..SupervisorDriverState::default()
        }));
        let (events_tx, events_rx) = mpsc::channel(2);
        let (idle_deadline_tx, mut idle_deadline_rx) = mpsc::unbounded_channel();
        let supervisor = super::ProviderRuntimeSupervisor::start(
            engine.clone(),
            Arc::new(SupervisorFactory {
                state: state.clone(),
                events: StdMutex::new(Some(events_rx)),
            }),
            super::ActivityProjection::new(crate::activity::ActivityRepository::new(
                engine.repositories().database().clone(),
            )),
            super::SupervisorOptions {
                queue_capacity: 2,
                session_idle_timeout: IDLE_TIMEOUT,
                open_url: None,
                idle_deadline_test_observer: Some(idle_deadline_tx),
                accepted_publication_test_hook: None,
            },
        );
        let temp = TempDir::new().unwrap();
        let mut request = native_launch(&temp, "codex");
        request.thread_id = "t1".to_owned();
        supervisor.launch(request).await.unwrap();

        for (event_type, payload) in [
            (
                "content.delta",
                json!({"messageId":"assistant-idle","delta":"OK"}),
            ),
            (
                "turn.completed",
                json!({"messageId":"assistant-idle","state":"completed"}),
            ),
        ] {
            events_tx
                .send(super::ProviderEvent {
                    native_event_id: None,
                    event_type: event_type.to_owned(),
                    thread_id: "t1".to_owned(),
                    turn_id: Some("unit-turn".to_owned()),
                    item_id: None,
                    request_id: None,
                    payload,
                    activity: Vec::new(),
                    activity_controls: Default::default(),
                })
                .await
                .unwrap();
        }

        timeout(Duration::from_secs(5), async {
            loop {
                let projected = load_snapshot(&engine.repositories())
                    .await
                    .unwrap()
                    .messages
                    .iter()
                    .any(|message| message.message_id == "assistant-idle" && !message.is_streaming);
                if projected {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("first completed assistant message is projected");
        assert_eq!(
            idle_deadline_rx.recv().await,
            Some(super::IdleDeadlineTestEvent::Armed { generation: 1 })
        );
        let follow_up: OrchestrationCommand = serde_json::from_value(json!({
            "type":"thread.turn.start", "commandId":"follow-up", "threadId":"t1",
            "message":{"messageId":"user-follow-up","role":"user","text":"next","attachments":[]},
            "modelSelection":{"instanceId":"codex","model":"gpt-5"},
            "runtimeMode":"full-access", "interactionMode":"default",
            "createdAt":"2026-07-16T00:00:01Z"
        }))
        .unwrap();
        supervisor.handle_orchestration(follow_up).await.unwrap();
        tokio::time::pause();
        tokio::time::advance(IDLE_TIMEOUT).await;
        assert_eq!(
            idle_deadline_rx.recv().await,
            Some(super::IdleDeadlineTestEvent::Evaluated {
                generation: 1,
                outcome: super::IdleDeadlineEvaluation::Stale,
            })
        );
        assert!(
            supervisor
                .capture_session_identity("t1")
                .await
                .unwrap()
                .is_some(),
            "the stale pre-follow-up idle deadline must not suspend the session"
        );
        assert_eq!(state.lock().unwrap().shutdowns, 0);
        tokio::time::resume();

        for (event_type, payload) in [
            (
                "content.delta",
                json!({"messageId":"assistant-follow-up","delta":"OK"}),
            ),
            (
                "turn.completed",
                json!({"messageId":"assistant-follow-up","state":"completed"}),
            ),
        ] {
            events_tx
                .send(super::ProviderEvent {
                    native_event_id: None,
                    event_type: event_type.to_owned(),
                    thread_id: "t1".to_owned(),
                    turn_id: Some("unit-turn-follow-up".to_owned()),
                    item_id: None,
                    request_id: None,
                    payload,
                    activity: Vec::new(),
                    activity_controls: Default::default(),
                })
                .await
                .unwrap();
        }
        timeout(Duration::from_secs(5), async {
            loop {
                let projected = load_snapshot(&engine.repositories())
                    .await
                    .unwrap()
                    .messages
                    .iter()
                    .any(|message| {
                        message.message_id == "assistant-follow-up" && !message.is_streaming
                    });
                if projected {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("follow-up completed assistant message is projected");
        assert_eq!(
            idle_deadline_rx.recv().await,
            Some(super::IdleDeadlineTestEvent::Armed { generation: 3 })
        );
        tokio::time::pause();
        tokio::time::advance(IDLE_TIMEOUT).await;
        assert_eq!(
            idle_deadline_rx.recv().await,
            Some(super::IdleDeadlineTestEvent::Evaluated {
                generation: 3,
                outcome: super::IdleDeadlineEvaluation::Suspended,
            })
        );
        assert!(
            supervisor
                .capture_session_identity("t1")
                .await
                .unwrap()
                .is_none(),
            "the current idle deadline suspends the session"
        );
        assert_eq!(state.lock().unwrap().shutdowns, 1);
        tokio::time::resume();

        let runtime = engine
            .repositories()
            .get_provider_session_runtime("t1".to_owned())
            .await
            .unwrap()
            .expect("resume state is retained");
        assert_eq!(runtime.status, "suspended");
        assert_eq!(
            runtime.resume_cursor,
            Some(json!({"threadId":"unit-session"}))
        );

        let stop: OrchestrationCommand = serde_json::from_value(json!({
            "type":"thread.session.stop", "commandId":"stop-idle", "threadId":"t1",
            "createdAt":"2026-07-16T00:00:02Z"
        }))
        .unwrap();
        supervisor.handle_orchestration(stop).await.unwrap();
        assert!(
            engine
                .repositories()
                .get_provider_session_runtime("t1".to_owned())
                .await
                .unwrap()
                .is_none(),
            "stopping a suspended session removes its resume state"
        );
        assert_eq!(state.lock().unwrap().shutdowns, 1);

        supervisor.shutdown().await.unwrap();
        engine.shutdown().await;
    }

    #[derive(Clone, Copy, Debug)]
    enum InterruptResponse {
        Settles,
        IgnoresInterrupt,
        NeverAnswers,
        /// A late Stop names a turn that is no longer the running one.
        StaleTurn,
        /// The turn's terminal projection is admitted but unfinished when the deadline fires.
        SettlesDuringRetirement,
        /// An external server keeps working after detachment, so retiring it cannot stop it.
        ExternallyOwned,
    }

    #[tokio::test]
    async fn interrupt_that_settles_in_time_keeps_the_session() {
        interrupt_deadline_case(InterruptResponse::Settles).await;
    }

    #[tokio::test]
    async fn interrupt_the_provider_ignores_retires_the_session_at_its_deadline() {
        interrupt_deadline_case(InterruptResponse::IgnoresInterrupt).await;
    }

    #[tokio::test]
    async fn interrupt_the_provider_never_answers_retires_the_session_at_its_deadline() {
        interrupt_deadline_case(InterruptResponse::NeverAnswers).await;
    }

    #[tokio::test]
    async fn stale_interrupt_for_another_turn_keeps_the_running_session() {
        interrupt_deadline_case(InterruptResponse::StaleTurn).await;
    }

    #[tokio::test]
    async fn interrupt_deadline_keeps_an_externally_owned_session_running() {
        interrupt_deadline_case(InterruptResponse::ExternallyOwned).await;
    }

    #[tokio::test]
    async fn interrupt_deadline_does_not_overwrite_a_settlement_it_raced() {
        interrupt_deadline_case(InterruptResponse::SettlesDuringRetirement).await;
    }

    // One case per test: each needs its own paused clock.
    async fn interrupt_deadline_case(response: InterruptResponse) {
        {
            let engine = supervisor_engine().await;
            let entered = Arc::new(tokio::sync::Notify::new());
            let first = Arc::new(StdMutex::new(SupervisorDriverState {
                interrupt_entered: Some(entered.clone()),
                interrupt_never_returns: matches!(response, InterruptResponse::NeverAnswers),
                externally_owned: matches!(response, InterruptResponse::ExternallyOwned),
                ..SupervisorDriverState::default()
            }));
            let second = Arc::new(StdMutex::new(SupervisorDriverState::default()));
            let (first_events, first_rx) = mpsc::channel(2);
            let (_second_events, second_rx) = mpsc::channel(2);
            let supervisor = super::ProviderRuntimeSupervisor::start(
                engine.clone(),
                Arc::new(SequencedSupervisorFactory {
                    drivers: StdMutex::new(
                        [(first.clone(), first_rx), (second.clone(), second_rx)].into(),
                    ),
                }),
                super::ActivityProjection::new(crate::activity::ActivityRepository::new(
                    engine.repositories().database().clone(),
                )),
                super::SupervisorOptions::default(),
            );
            let workspace = TempDir::new().unwrap();
            let mut request = native_launch(&workspace, "codex");
            request.thread_id = "t1".to_owned();
            supervisor.launch(request.clone()).await.unwrap();
            let start = |id: &str| -> OrchestrationCommand {
                serde_json::from_value(json!({
                    "type":"thread.turn.start", "commandId":id, "threadId":"t1",
                    "message":{"messageId":format!("user-{id}"),"role":"user","text":id,"attachments":[]},
                    "runtimeMode":"full-access", "interactionMode":"default",
                    "createdAt":"2026-07-16T00:00:01Z"
                }))
                .unwrap()
            };
            let session = || async {
                engine
                    .repositories()
                    .get_thread_session("t1".to_owned())
                    .await
                    .unwrap()
                    .expect("projected session")
            };
            supervisor
                .handle_orchestration(start("first"))
                .await
                .unwrap();
            assert_eq!(session().await.status, "running");

            tokio::time::pause();
            let clock = keep_idle_clock_paused();
            let requested_turn = if matches!(response, InterruptResponse::StaleTurn) {
                "earlier-turn"
            } else {
                "unit-turn"
            };
            let mut interrupt =
                Some(tokio::spawn({
                    let supervisor = supervisor.clone();
                    async move {
                        supervisor
                        .handle_orchestration(serde_json::from_value(json!({
                            "type":"thread.turn.interrupt", "commandId":"stop", "threadId":"t1",
                            "turnId":requested_turn, "createdAt":"2026-07-16T00:00:02Z"
                        })).unwrap())
                        .await
                    }
                }));
            entered.notified().await;
            let completion = super::ProviderEvent {
                native_event_id: None,
                event_type: "turn.completed".to_owned(),
                thread_id: "t1".to_owned(),
                turn_id: Some("unit-turn".to_owned()),
                item_id: None,
                request_id: None,
                payload: json!({"state":"interrupted"}),
                activity: Vec::new(),
                activity_controls: Default::default(),
            };
            if matches!(response, InterruptResponse::StaleTurn) {
                interrupt.take().unwrap().await.unwrap().unwrap();
            }
            let mut held_settlement = None;
            if matches!(response, InterruptResponse::SettlesDuringRetirement) {
                interrupt.take().unwrap().await.unwrap().unwrap();
                let held = engine.test_hooks().pause_before_next_command_persist();
                first_events.send(completion.clone()).await.unwrap();
                held.wait_until_entered().await;
                held_settlement = Some(held);
            }
            if matches!(response, InterruptResponse::Settles) {
                interrupt.take().unwrap().await.unwrap().unwrap();
                first_events.send(completion).await.unwrap();
                let started = Instant::now();
                while session().await.status != "ready" {
                    assert!(started.elapsed() < Duration::from_secs(5), "turn settles");
                    tokio::task::yield_now().await;
                }
            }
            // Timer deadlines round up to the next millisecond.
            tokio::time::advance(
                super::PROVIDER_INTERRUPT_SETTLEMENT_TIMEOUT + Duration::from_millis(1),
            )
            .await;
            if let Some(interrupt) = interrupt.take() {
                interrupt
                    .await
                    .unwrap()
                    .expect("Stop returns once the provider is given up on");
            }
            if let Some(held) = held_settlement {
                // Let the actor check the still-running projection and wait on detachment.
                let started = Instant::now();
                while started.elapsed() < Duration::from_millis(300) {
                    tokio::task::yield_now().await;
                }
                held.release();
            }
            // The deadline is evaluated on the actor; a round trip orders after it.
            let started = Instant::now();
            let retired = loop {
                let live = supervisor
                    .capture_session_identity("t1")
                    .await
                    .unwrap()
                    .is_some();
                let status = session().await.status;
                let kept = matches!(
                    response,
                    InterruptResponse::Settles
                        | InterruptResponse::StaleTurn
                        | InterruptResponse::ExternallyOwned
                );
                let raced = matches!(response, InterruptResponse::SettlesDuringRetirement);
                if kept || raced && !live || !live && status != "running" {
                    break !live;
                }
                assert!(
                    started.elapsed() < Duration::from_secs(5),
                    "{response:?}: the unsettled turn is retired at its deadline"
                );
                tokio::task::yield_now().await;
            };
            drop(clock);
            tokio::time::resume();

            if matches!(
                response,
                InterruptResponse::Settles
                    | InterruptResponse::StaleTurn
                    | InterruptResponse::ExternallyOwned
            ) {
                assert!(!retired, "{response:?}: the session is kept");
                assert_eq!(first.lock().unwrap().shutdowns, 0);
                if matches!(response, InterruptResponse::ExternallyOwned) {
                    assert_eq!(session().await.status, "running");
                }
                supervisor.shutdown().await.unwrap();
                engine.shutdown().await;
                return;
            }
            assert_eq!(first.lock().unwrap().shutdowns, 1, "{response:?}");
            if matches!(response, InterruptResponse::SettlesDuringRetirement) {
                // Retired, but the provider's own settlement stands.
                let projected = session().await;
                assert_eq!(projected.status, "ready");
                assert_eq!(projected.last_error, None);
                supervisor.shutdown().await.unwrap();
                engine.shutdown().await;
                return;
            }
            let projected = session().await;
            assert_eq!(projected.status, "interrupted", "{response:?}");
            assert_eq!(projected.active_turn_id, None);
            assert_eq!(
                projected.last_error_class.as_deref(),
                Some("session_stopped")
            );
            let runtime = engine
                .repositories()
                .get_provider_session_runtime("t1".to_owned())
                .await
                .unwrap()
                .expect("resume state is retained");
            assert_eq!(runtime.status, "suspended");
            assert_eq!(
                runtime.resume_cursor,
                Some(json!({"threadId":"unit-session"}))
            );

            // The next message starts a fresh provider session.
            supervisor.launch(request).await.unwrap();
            supervisor
                .handle_orchestration(start("second"))
                .await
                .unwrap();
            assert_eq!(second.lock().unwrap().sends, vec!["second".to_owned()]);
            assert_eq!(session().await.status, "running");
            supervisor.shutdown().await.unwrap();
            engine.shutdown().await;
        }
    }

    const BUSY_SESSION_IDLE_TIMEOUT: Duration = Duration::from_secs(30);

    // SQLite runs on another thread. Keep paused Tokio time from auto-advancing
    // to a deadline while a test is only waiting for a database round trip.
    fn keep_idle_clock_paused() -> tokio_util::task::AbortOnDropHandle<()> {
        tokio_util::task::AbortOnDropHandle::new(tokio::spawn(async {
            loop {
                tokio::task::yield_now().await;
            }
        }))
    }

    struct IdleDeadlineFixture {
        engine: super::OrchestrationEngine,
        supervisor: super::ProviderRuntimeSupervisor,
        state: Arc<StdMutex<SupervisorDriverState>>,
        events: mpsc::Sender<super::ProviderEvent>,
        deadlines: mpsc::UnboundedReceiver<super::IdleDeadlineTestEvent>,
        idle_timeout: Duration,
        admission_waiting: Arc<tokio::sync::Notify>,
        activity: super::ActivityProjection,
        _workspace: TempDir,
    }

    impl IdleDeadlineFixture {
        async fn new(idle_timeout: Duration) -> Self {
            Self::new_for_provider(idle_timeout, "codex").await
        }

        async fn new_for_provider(idle_timeout: Duration, provider: &str) -> Self {
            let engine = supervisor_engine().await;
            let state = Arc::new(StdMutex::new(SupervisorDriverState {
                send_turn_ids: ["idle-turn-1".to_owned(), "idle-turn-2".to_owned()].into(),
                activity_capabilities: crate::activity::ActivityCapabilities::structured_full(
                    false,
                ),
                ..SupervisorDriverState::default()
            }));
            let (events, events_rx) = mpsc::channel(2);
            let (idle_deadline_tx, deadlines) = mpsc::unbounded_channel();
            let admission_waiting = Arc::new(tokio::sync::Notify::new());
            let activity = super::ActivityProjection::new(
                crate::activity::ActivityRepository::new(engine.repositories().database().clone()),
            );
            let supervisor = super::ProviderRuntimeSupervisor::start(
                engine.clone(),
                Arc::new(SupervisorFactory {
                    state: state.clone(),
                    events: StdMutex::new(Some(events_rx)),
                }),
                activity.clone(),
                super::SupervisorOptions {
                    queue_capacity: 2,
                    session_idle_timeout: idle_timeout,
                    open_url: None,
                    idle_deadline_test_observer: Some(idle_deadline_tx),
                    accepted_publication_test_hook: Some(super::AcceptedPublicationTestHook {
                        admission_waiting: Some(admission_waiting.clone()),
                        ..super::AcceptedPublicationTestHook::default()
                    }),
                },
            );
            let workspace = TempDir::new().unwrap();
            let mut request = native_launch(&workspace, provider);
            request.thread_id = "t1".to_owned();
            supervisor.launch(request).await.unwrap();
            Self {
                engine,
                supervisor,
                state,
                events,
                deadlines,
                idle_timeout,
                admission_waiting,
                activity,
                _workspace: workspace,
            }
        }

        fn turn_command(id: &str) -> OrchestrationCommand {
            // A model selection would dispatch through the paused engine before
            // Deliver can return its admission handle.
            serde_json::from_value(json!({
                "type":"thread.turn.start", "commandId":id, "threadId":"t1",
                "message":{"messageId":format!("user-{id}"),"role":"user","text":id,"attachments":[]},
                "runtimeMode":"full-access", "interactionMode":"default",
                "createdAt":"2026-07-16T00:00:01Z"
            }))
            .unwrap()
        }

        async fn admit(&self, id: &str) -> super::ProviderDeliveryHandle {
            let handle = self
                .supervisor
                .deliver_turn(Self::turn_command(id), id.to_owned())
                .await
                .expect("turn admitted");
            self.admission_waiting.notified().await;
            handle
        }

        async fn queue_admission_behind_settlement(
            &self,
            id: &str,
        ) -> tokio::task::JoinHandle<super::ProviderDeliveryHandle> {
            let supervisor = self.supervisor.clone();
            let command = Self::turn_command(id);
            let key = id.to_owned();
            let attempt = tokio::spawn(async move {
                supervisor
                    .deliver_turn(command, key)
                    .await
                    .expect("turn admitted after settlement")
            });
            self.admission_waiting.notified().await;
            // The actor reserved the delivery/idle generation, but native admission must
            // wait until the previous terminal batch completes. Release its test gate
            // before awaiting the returned handle to avoid a fixture-only wait cycle.
            attempt
        }

        async fn accepted(handle: super::ProviderDeliveryHandle, turn_id: &str) {
            assert_eq!(
                handle.completion().await,
                super::ProviderDeliveryOutcome::Accepted {
                    turn_id: Some(turn_id.to_owned())
                }
            );
        }

        async fn emit(&self, event_type: &str, turn_id: &str, message_id: &str) {
            self.events
                .send(super::ProviderEvent {
                    native_event_id: None,
                    event_type: event_type.to_owned(),
                    thread_id: "t1".to_owned(),
                    turn_id: Some(turn_id.to_owned()),
                    item_id: None,
                    request_id: None,
                    payload: json!({"messageId":message_id,"delta":"OK","state":"completed"}),
                    activity: Vec::new(),
                    activity_controls: Default::default(),
                })
                .await
                .unwrap();
        }

        async fn emit_payload(&self, event_type: &str, turn_id: &str, payload: Value) {
            self.events
                .send(super::ProviderEvent {
                    native_event_id: None,
                    event_type: event_type.to_owned(),
                    thread_id: "t1".to_owned(),
                    turn_id: Some(turn_id.to_owned()),
                    item_id: None,
                    request_id: None,
                    payload,
                    activity: Vec::new(),
                    activity_controls: Default::default(),
                })
                .await
                .unwrap();
        }

        async fn emit_activity(&self, native_event_id: &str, mutation: ProviderActivityMutation) {
            self.emit_activity_batch(native_event_id, vec![mutation])
                .await;
        }

        /// Sends an activity-only batch and waits until the pump has projected it.
        async fn emit_activity_batch(
            &self,
            native_event_id: &str,
            mutations: Vec<ProviderActivityMutation>,
        ) {
            // The pump records the batch before it yields after publishing this completion.
            let mut applied = self
                .activity
                .subscribe_apply_completions_for_integration_test();
            self.events
                .send(super::ProviderEvent {
                    native_event_id: Some(
                        super::ProviderNativeEventId::new(native_event_id.to_owned()).unwrap(),
                    ),
                    event_type: super::ACTIVITY_ONLY_PROVIDER_EVENT_TYPE.to_owned(),
                    thread_id: "t1".to_owned(),
                    turn_id: None,
                    item_id: None,
                    request_id: None,
                    payload: json!({}),
                    activity: mutations,
                    activity_controls: Default::default(),
                })
                .await
                .unwrap();
            applied.recv().await.expect("activity batch projected");
        }

        /// Completes the first turn after a subagent actor reached `status`.
        async fn complete_first_turn_with_actor(&mut self, status: &str) {
            Self::accepted(self.admit("first").await, "idle-turn-1").await;
            self.stream("idle-turn-1", "assistant-first").await;
            self.emit_activity(
                "subagent-start",
                ProviderActivityMutation::upsert_actor("actor:sub", None, "Sub", status).unwrap(),
            )
            .await;
            self.emit("turn.completed", "idle-turn-1", "assistant-first")
                .await;
            assert_eq!(
                self.next_deadline().await,
                super::IdleDeadlineTestEvent::Armed { generation: 2 }
            );
        }

        async fn assert_busy_after_timeout(&mut self, generation: u64, reason: &str) {
            tokio::time::advance(self.idle_timeout).await;
            let evaluated = self.next_deadline().await;
            self.assert_live(reason).await;
            assert_eq!(
                evaluated,
                super::IdleDeadlineTestEvent::Evaluated {
                    generation,
                    outcome: super::IdleDeadlineEvaluation::Busy,
                }
            );
            assert_eq!(
                self.next_deadline().await,
                super::IdleDeadlineTestEvent::Armed {
                    generation: generation + 1
                }
            );
        }

        async fn stream(&self, turn_id: &str, message_id: &str) {
            self.emit("content.delta", turn_id, message_id).await;
            let started = Instant::now();
            loop {
                if self
                    .engine
                    .repositories()
                    .get_message(message_id.to_owned())
                    .await
                    .unwrap()
                    .is_some_and(|message| {
                        message.is_streaming && message.turn_id.as_deref() == Some(turn_id)
                    })
                {
                    break;
                }
                assert!(
                    started.elapsed() < Duration::from_secs(5),
                    "delta persisted"
                );
                tokio::task::yield_now().await;
            }
        }

        async fn hold_completion_settlement(
            &self,
            turn_id: &str,
            message_id: &str,
        ) -> crate::orchestration::engine::AdmissionCommitPause {
            // The hooks are unfiltered and take-once. No other command producer
            // may run until both pauses have caught the completion's commands.
            self.stream(turn_id, message_id).await;
            let hooks = self.engine.test_hooks();
            let ready = hooks.pause_before_next_command_persist();
            self.emit("turn.completed", turn_id, message_id).await;
            ready.wait_until_entered().await;
            let settlement = hooks.pause_before_next_command_persist();
            ready.release();
            settlement.wait_until_entered().await;
            self.assert_projection("ready", None).await;
            settlement
        }

        async fn assert_projection(&self, status: &str, turn_id: Option<&str>) {
            let session = self
                .engine
                .repositories()
                .get_thread_session("t1".to_owned())
                .await
                .unwrap()
                .expect("projected session");
            assert_eq!(session.status, status);
            assert_eq!(session.active_turn_id.as_deref(), turn_id);
        }

        async fn assert_live(&self, reason: &str) {
            let session = self
                .engine
                .repositories()
                .get_thread_session("t1".to_owned())
                .await
                .unwrap()
                .expect("projected session");
            let runtime = self
                .engine
                .repositories()
                .get_provider_session_runtime("t1".to_owned())
                .await
                .unwrap()
                .expect("runtime row");
            let live = self
                .supervisor
                .capture_session_identity("t1")
                .await
                .unwrap()
                .is_some();
            let shutdowns = self.state.lock().unwrap().shutdowns;
            assert!(
                live && shutdowns == 0 && runtime.status != "suspended",
                "{reason}; projected status={} active_turn={:?}; runtime status={} (no active-turn field); live={live}, shutdowns={shutdowns}",
                session.status,
                session.active_turn_id,
                runtime.status,
            );
        }

        async fn next_deadline(&mut self) -> super::IdleDeadlineTestEvent {
            self.deadlines.recv().await.expect("idle deadline event")
        }

        async fn assert_settled(&self, message_id: &str, turn_id: &str) {
            let snapshot = load_snapshot(&self.engine.repositories()).await.unwrap();
            assert!(
                snapshot
                    .messages
                    .iter()
                    .any(|message| { message.message_id == message_id && !message.is_streaming })
            );
            assert!(snapshot.activities.iter().any(|activity| {
                activity.summary == "Turn completed" && activity.turn_id.as_deref() == Some(turn_id)
            }));
        }

        async fn finish_follow_up(&mut self) {
            self.stream("idle-turn-2", "assistant-follow-up").await;
            self.emit("turn.completed", "idle-turn-2", "assistant-follow-up")
                .await;
            let armed = self.next_deadline().await;
            self.assert_settled("assistant-follow-up", "idle-turn-2")
                .await;
            assert_eq!(armed, super::IdleDeadlineTestEvent::Armed { generation: 4 });
            self.assert_suspended_after_timeout(4).await;
        }

        async fn assert_suspended_after_timeout(&mut self, generation: u64) {
            tokio::time::advance(self.idle_timeout).await;
            let evaluated = self.next_deadline().await;
            assert!(
                self.supervisor
                    .capture_session_identity("t1")
                    .await
                    .unwrap()
                    .is_none(),
                "the completed idle session is suspended"
            );
            assert_eq!(self.state.lock().unwrap().shutdowns, 1);
            let runtime = self
                .engine
                .repositories()
                .get_provider_session_runtime("t1".to_owned())
                .await
                .unwrap()
                .expect("suspension preserves resume state");
            assert_eq!(runtime.status, "suspended");
            assert_eq!(
                runtime.resume_cursor,
                Some(json!({"threadId":"unit-session"}))
            );
            self.assert_projection("ready", None).await;
            assert_eq!(
                evaluated,
                super::IdleDeadlineTestEvent::Evaluated {
                    generation,
                    outcome: super::IdleDeadlineEvaluation::Suspended,
                }
            );
        }

        async fn close(self) {
            self.supervisor.shutdown().await.unwrap();
            self.engine.shutdown().await;
        }
    }

    #[test]
    fn idle_rearm_reservation_preserves_a_completion_generation() {
        let idle_generation = AtomicU64::new(7);
        assert_eq!(super::reserve_idle_rearm(&idle_generation, 7), Some(8));
        assert_eq!(idle_generation.load(Ordering::Relaxed), 8);

        // The event pump reserves the completion before the busy deadline re-arms.
        idle_generation.fetch_add(1, Ordering::Relaxed);
        assert_eq!(super::reserve_idle_rearm(&idle_generation, 8), None);
        assert_eq!(idle_generation.load(Ordering::Relaxed), 9);
    }

    #[tokio::test(start_paused = true)]
    async fn idle_deadline_ignores_a_send_admitted_before_it_was_armed() {
        let _clock = keep_idle_clock_paused();
        let mut fixture = IdleDeadlineFixture::new(BUSY_SESSION_IDLE_TIMEOUT).await;
        IdleDeadlineFixture::accepted(fixture.admit("first").await, "idle-turn-1").await;
        let settlement = fixture
            .hold_completion_settlement("idle-turn-1", "assistant-first")
            .await;
        let follow_up = fixture.queue_admission_behind_settlement("follow-up").await;
        settlement.release();
        let follow_up = follow_up.await.unwrap();
        IdleDeadlineFixture::accepted(follow_up, "idle-turn-2").await;
        fixture
            .assert_projection("running", Some("idle-turn-2"))
            .await;
        let armed = fixture.next_deadline().await;

        tokio::time::advance(BUSY_SESSION_IDLE_TIMEOUT).await;
        let evaluated = fixture.next_deadline().await;
        fixture
            .assert_live(
                "F23: the idle deadline suspended the session while the admitted turn was running",
            )
            .await;
        fixture
            .assert_projection("running", Some("idle-turn-2"))
            .await;
        assert_eq!(armed, super::IdleDeadlineTestEvent::Armed { generation: 2 });
        assert_eq!(
            evaluated,
            super::IdleDeadlineTestEvent::Evaluated {
                generation: 2,
                outcome: super::IdleDeadlineEvaluation::Stale,
            }
        );

        fixture.finish_follow_up().await;
        fixture.close().await;
    }

    #[tokio::test(start_paused = true)]
    async fn idle_deadline_ignores_a_delivery_still_in_flight() {
        let _clock = keep_idle_clock_paused();
        let mut fixture = IdleDeadlineFixture::new(BUSY_SESSION_IDLE_TIMEOUT).await;
        IdleDeadlineFixture::accepted(fixture.admit("first").await, "idle-turn-1").await;
        let settlement = fixture
            .hold_completion_settlement("idle-turn-1", "assistant-first")
            .await;
        let gate = Arc::new(tokio::sync::Notify::new());
        let entered = Arc::new(tokio::sync::Notify::new());
        {
            let mut state = fixture.state.lock().unwrap();
            state.send_gate = Some(gate.clone());
            state.send_entered = Some(entered.clone());
        }
        let follow_up = fixture.queue_admission_behind_settlement("follow-up").await;
        settlement.release();
        let follow_up = follow_up.await.unwrap();
        entered.notified().await;
        let armed = fixture.next_deadline().await;
        fixture.assert_projection("ready", None).await;

        tokio::time::advance(BUSY_SESSION_IDLE_TIMEOUT).await;
        let evaluated = fixture.next_deadline().await;
        fixture
            .assert_live("F23: the idle deadline suspended a delivery still in flight")
            .await;
        fixture.assert_projection("ready", None).await;
        assert_eq!(armed, super::IdleDeadlineTestEvent::Armed { generation: 2 });
        assert_eq!(
            evaluated,
            super::IdleDeadlineTestEvent::Evaluated {
                generation: 2,
                outcome: super::IdleDeadlineEvaluation::Stale,
            }
        );

        gate.notify_one();
        IdleDeadlineFixture::accepted(follow_up, "idle-turn-2").await;
        fixture.finish_follow_up().await;
        fixture.close().await;
    }

    #[tokio::test(start_paused = true)]
    async fn idle_deadline_does_not_interrupt_completion_settlement() {
        let _clock = keep_idle_clock_paused();
        let mut fixture = IdleDeadlineFixture::new(BUSY_SESSION_IDLE_TIMEOUT).await;
        IdleDeadlineFixture::accepted(fixture.admit("first").await, "idle-turn-1").await;
        let first_settlement = fixture
            .hold_completion_settlement("idle-turn-1", "assistant-first")
            .await;
        let follow_up = fixture.queue_admission_behind_settlement("follow-up").await;
        first_settlement.release();
        let follow_up = follow_up.await.unwrap();
        IdleDeadlineFixture::accepted(follow_up, "idle-turn-2").await;
        let first_armed = fixture.next_deadline().await;
        let settlement = fixture
            .hold_completion_settlement("idle-turn-2", "assistant-follow-up")
            .await;

        tokio::time::advance(BUSY_SESSION_IDLE_TIMEOUT).await;
        let evaluated = fixture.next_deadline().await;
        fixture
            .assert_live("F23: the idle deadline interrupted completion settlement")
            .await;
        assert!(
            fixture
                .engine
                .repositories()
                .get_message("assistant-follow-up".to_owned())
                .await
                .unwrap()
                .unwrap()
                .is_streaming,
            "the completion is held before settling the assistant message"
        );
        assert_eq!(
            first_armed,
            super::IdleDeadlineTestEvent::Armed { generation: 2 }
        );
        assert_eq!(
            evaluated,
            super::IdleDeadlineTestEvent::Evaluated {
                generation: 2,
                outcome: super::IdleDeadlineEvaluation::Stale,
            }
        );

        settlement.release();
        let armed = fixture.next_deadline().await;
        fixture
            .assert_settled("assistant-follow-up", "idle-turn-2")
            .await;
        assert_eq!(armed, super::IdleDeadlineTestEvent::Armed { generation: 4 });
        fixture.assert_suspended_after_timeout(4).await;
        fixture.close().await;
    }

    #[tokio::test(start_paused = true)]
    async fn idle_deadline_rearms_while_the_projection_is_busy() {
        let _clock = keep_idle_clock_paused();
        let mut fixture = IdleDeadlineFixture::new(BUSY_SESSION_IDLE_TIMEOUT).await;
        IdleDeadlineFixture::accepted(fixture.admit("first").await, "idle-turn-1").await;
        fixture.stream("idle-turn-1", "assistant-first").await;
        fixture
            .emit("turn.completed", "idle-turn-1", "assistant-first")
            .await;
        let armed = fixture.next_deadline().await;

        // Exercise the guard independently of Deliver's generation bump.
        fixture.engine.dispatch(serde_json::from_value(json!({
            "type":"thread.session.set", "commandId":"busy-projection", "threadId":"t1",
            "session":{"threadId":"t1","status":"running","providerName":"codex",
                "providerInstanceId":"codex","runtimeMode":"full-access",
                "activeTurnId":"external-turn","lastError":null,"updatedAt":"2026-07-16T00:00:02Z"},
            "createdAt":"2026-07-16T00:00:02Z"
        })).unwrap()).await.unwrap();
        tokio::time::advance(BUSY_SESSION_IDLE_TIMEOUT).await;
        let evaluated = fixture.next_deadline().await;
        fixture
            .assert_live("F23: the idle deadline suspended a busy projection instead of re-arming")
            .await;
        fixture
            .assert_projection("running", Some("external-turn"))
            .await;
        assert_eq!(armed, super::IdleDeadlineTestEvent::Armed { generation: 2 });
        assert_eq!(
            evaluated,
            super::IdleDeadlineTestEvent::Evaluated {
                generation: 2,
                outcome: super::IdleDeadlineEvaluation::Busy,
            }
        );
        assert_eq!(
            fixture.next_deadline().await,
            super::IdleDeadlineTestEvent::Armed { generation: 3 }
        );

        fixture
            .engine
            .dispatch(
                serde_json::from_value(json!({
                    "type":"thread.session.set", "commandId":"idle-projection", "threadId":"t1",
                    "session":{"threadId":"t1","status":"ready","providerName":"codex",
                        "providerInstanceId":"codex","runtimeMode":"full-access",
                        "activeTurnId":null,"lastError":null,"updatedAt":"2026-07-16T00:00:03Z"},
                    "createdAt":"2026-07-16T00:00:03Z"
                }))
                .unwrap(),
            )
            .await
            .unwrap();
        fixture.assert_suspended_after_timeout(3).await;
        fixture.close().await;
    }

