    #[test]
    fn provider_item_ids_are_opaque_and_reject_raw_whitespace_or_controls() {
        let message_id = |item_id: &str| {
            super::assistant_message_id(&ProviderEvent {
                native_event_id: None,
                event_type: "content.delta".to_owned(),
                thread_id: "thread-1".to_owned(),
                turn_id: Some("turn-1".to_owned()),
                item_id: Some(item_id.to_owned()),
                request_id: None,
                payload: json!({}),
                activity: Vec::new(),
                activity_controls: Default::default(),
            })
        };

        assert_eq!(message_id("message-1"), "assistant:thread-1:item:message-1");
        for malformed in [
            " message-1",
            "message-1 ",
            "message-1\t",
            "message-1\n",
            "message-1\r",
            "message-\u{0007}1",
        ] {
            assert_eq!(
                message_id(malformed),
                "assistant:thread-1:turn:turn-1",
                "malformed raw provider ID {malformed:?} must not alias the canonical ID"
            );
        }
    }

    #[test]
    fn provider_projection_helpers_preserve_contract_fallbacks() {
        let event = |payload, turn_id: Option<&str>| super::ProviderEvent {
            native_event_id: None,
            event_type: "provider.event".to_owned(),
            thread_id: "thread-1".to_owned(),
            turn_id: turn_id.map(str::to_owned),
            item_id: None,
            request_id: None,
            payload,
            activity: Vec::new(),
            activity_controls: Default::default(),
        };
        assert_eq!(
            super::assistant_message_id(&event(json!({"messageId":"message-1"}), Some("turn-1"))),
            "message-1"
        );
        assert_eq!(
            super::assistant_message_id(&event(json!({}), Some("turn-1"))),
            "assistant:thread-1:turn:turn-1"
        );
        assert_eq!(
            super::assistant_message_id(&event(json!({}), None)),
            "assistant:thread-1"
        );

        // `errorMessage` is what every provider runtime actually writes into a
        // failed `turn.completed` payload, so it must win over the raw shapes.
        assert_eq!(
            super::provider_completion_error(
                &json!({"state":"failed","errorMessage":"Reached the maximum number of turns."})
            ),
            "Reached the maximum number of turns."
        );
        assert_eq!(
            super::provider_completion_error(
                &json!({"errorMessage":"canonical","error":{"message":"nested"},"message":"top-level"})
            ),
            "canonical"
        );
        assert_eq!(
            super::provider_completion_error(&json!({"errorMessage":"   "})),
            "Provider turn failed."
        );
        assert_eq!(
            super::provider_completion_error(&json!({"error":{"message":"nested"}})),
            "nested"
        );
        assert_eq!(
            super::provider_completion_error(&json!({"error":"flat"})),
            "flat"
        );
        assert_eq!(
            super::provider_completion_error(&json!({"message":"top-level"})),
            "top-level"
        );
        assert_eq!(
            super::provider_completion_error(&json!({"error":{}})),
            "Provider turn failed."
        );

        for (event_type, expected) in [
            ("request.opened", ("approval", "approval.requested")),
            ("request.resolved", ("approval", "approval.resolved")),
            ("user-input.requested", ("approval", "user-input.requested")),
            ("user-input.resolved", ("approval", "user-input.resolved")),
            ("provider.failed", ("error", "provider.error")),
            // Provider warnings must not be filed as tool events.
            ("runtime.warning", ("warning", "provider.warning")),
            ("provider.error", ("error", "provider.error")),
            ("turn.started", ("info", "provider.turn")),
            ("session.ready", ("info", "provider.session")),
            ("tool.started", ("tool", "provider.event")),
        ] {
            assert_eq!(super::event_activity_shape(event_type), expected);
        }
    }

